pub(crate) fn emit_is_a_par_fold(rule: &GrammarRule) -> bool {
    for alt in rule.alts.iter() {
        match &alt.pattern.node {
            Pattern::Fold(spec) => { if spec.parallel { return true; } },
            Pattern::Bind { pat, .. } => {
                let pat = nikaia_std::boxed::open(pat);
                match &pat.node {
                    Pattern::Fold(spec) => { if spec.parallel { return true; } },
                    _ => { },
                }
            },
            _ => { },
        }
    }
    false
}

pub(crate) fn emit_either_at(world: &EmitWorld<'_, '_, '_, '_>, item: &Item, own: &str, at: i64) -> i64 {
    match item {
        Item::Fn { name, args, .. } => {
            let name = *name;
            let called = match name { Some(__nikaia_value) => __nikaia_value, None => return -1 };
            if world.words.resolve(called) != own { return -1; }
            if at < args.len() as i64 && nikaia_std::index::get(&args, nikaia_std::index::at(at)).ty.either { return 1; }
            return 0;
        },
        _ => { },
    }
    -1
}

pub(crate) fn emit_callee_text(world: &EmitWorld<'_, '_, '_, '_>, func: &Expr) -> Option<String> {
    match func {
        Expr::Variable(name, _) => {
            let name = *name;
            return Some(world.words.resolve(name).to_owned());
        },
        Expr::Path(segments, _) => {
            let mut parts: Vec<String> = vec![];
            for segment in segments.iter() {
                let segment = *segment;
                parts.push(world.words.resolve(segment).to_owned());
            }
            return Some(parts.join("::"));
        },
        _ => { },
    }
    None
}

