impl EmitState {
    pub fn path(&self, world: &EmitWorld<'_, '_, '_, '_>, trusting: bool, unpinned: bool, segments: &[String]) -> String {
        if segments.len() == 2 && *nikaia_std::index::get(&segments, 1) == "new" {
            if unpinned && (*nikaia_std::index::get(&segments, 0) == "HashMap" || *nikaia_std::index::get(&segments, 0) == "HashSet") { return format!("{}::default", *nikaia_std::index::get(&segments, 0)); }
            let chosen = self.map_name(trusting, nikaia_std::index::get(&segments, 0));
            if chosen == "HashMap" { return String::from("HashMap::<_, _>::default"); }
            if chosen != *nikaia_std::index::get(&segments, 0) { return format!("{}::default", chosen); }
        }
        let mut mapped: Vec<String> = vec![];
        for segment in segments.iter() { mapped.push(self.map_name(trusting, segment)); }
        let joined = mapped.join("::");
        unaliased_in(world.aliases, &joined)
    }
    pub fn written_name(&self, world: &EmitWorld<'_, '_, '_, '_>, crossings: bool, trusting: bool, name: &str, count: Count) -> String {
        if name == "Shared" { return rust_name(count); }
        if name == "Locked" {
            if !crossings { return lock_name(Count::Plain); }
            return lock_name(count);
        }
        if name == "TaskHandle" && !self.structs.contains(name) && !self.structs_beside.contains(name) && !emit_below_an_enum_named(world, name) { return String::from("nikaia_std::task::TaskHandle"); }
        let mapped = self.mapped_path(trusting, name);
        unaliased_in(world.aliases, &mapped)
    }
    pub fn hull_new(&self, world: &EmitWorld<'_, '_, '_, '_>, crossings: bool, trusting: bool, name: &str, count: Count) -> Option<Vec<String>> {
        if name == "Shared" { return Some(vec![self.written_name(world, crossings, trusting, "Shared", count)]); }
        if name == "Locked" { return Some(vec![self.written_name(world, crossings, trusting, "Locked", count)]); }
        if name == "SharedMut" { return Some(vec![self.written_name(world, crossings, trusting, "Shared", count), self.written_name(world, crossings, trusting, "Locked", count)]); }
        None
    }
    pub fn attributes_read(&self, world: &EmitWorld<'_, '_, '_, '_>, wanted: &str, args: &[Expr], texts: &[String]) -> String {
        let mut written: String = String::from("");
        if !args.is_empty() { written = nikaia_std::index::or(emit_callee_text(world, nikaia_std::index::get(&args, 0)), || "".into()); }
        let asked = unaliased_in(world.aliases, &written);
        let mut values: Vec<String> = vec![];
        for text in texts.iter() {
            let parts: Vec<&str> = text.split(" { ").collect::<Vec<_>>();
            if *nikaia_std::index::get(&parts, 0) == asked { values.push(self.attribute_in_rust(world, text)); }
        }
        if wanted == "attribute" {
            if !values.is_empty() { return format!("Some({})", *nikaia_std::index::get(&values, 0)); }
            return format!("None::<{}>", asked);
        }
        if !values.is_empty() {
            let joined = values.join(", ");
            return format!("vec![{}]", joined);
        }
        format!("Vec::<{}>::new()", asked)
    }
}

pub fn emit_is_a_shape_bound(world: &EmitWorld<'_, '_, '_, '_>, bound: &str) -> bool {
    if bound != "Struct" && bound != "Enum" { return false; }
    for item in world.items.iter() {
        match &item.node {
            Item::Trait { name, .. } => {
                let name = *name;
                if escaped_name(world.words.resolve(name)) == bound { return false; }
            },
            _ => { },
        }
    }
    true
}

pub fn emit_bounded(world: &EmitWorld<'_, '_, '_, '_>, param: &GenericParam) -> String {
    let name = escaped_name(world.words.resolve(param.name));
    let mut bounds: Vec<String> = vec![];
    for bound in param.bounds.iter() {
        let bound = *bound;
        let written = escaped_name(world.words.resolve(bound));
        if !emit_is_a_shape_bound(world, &written) { bounds.push(written); }
    }
    if bounds.is_empty() { return name; }
    let joined = bounds.join(" + ");
    format!("{}: {}", name, joined)
}

pub(crate) fn emit_below_an_enum_named(world: &EmitWorld<'_, '_, '_, '_>, wanted: &str) -> bool {
    for item in world.items.iter() {
        match &item.node {
            Item::Enum { name, .. } => {
                let name = *name;
                if world.words.resolve(name) == wanted { return true; }
            },
            _ => { },
        }
    }
    false
}

pub(crate) fn emit_enters_a_parallel_rule(grammars: &collections::BTreeMap<String, GrammarDef>, world: &EmitWorld<'_, '_, '_, '_>, expr: &Expr) -> bool {
    match expr {
        Expr::Call { func, .. } => {
            let func = nikaia_std::boxed::open(func);
            match func {
                Expr::Path(segments, _) => {
                    if segments.len() != 2 { return false; }
                    let def = match grammars.get(world.words.resolve(*nikaia_std::index::get(&segments, 0))) { Some(__nikaia_value) => __nikaia_value, None => return false };
                    for rule in def.rules.iter() { if rule.is_entry && rule.name == *nikaia_std::index::get(&segments, 1) && emit_is_a_par_fold(rule) { return true; } }
                },
                _ => { },
            }
        },
        _ => { },
    }
    false
}

pub fn emit_uses_driver(world: &EmitWorld<'_, '_, '_, '_>, grammars: &collections::BTreeMap<String, GrammarDef>) -> bool {
    for item in world.items.iter() {
        match &item.node {
            Item::Fn { body, .. } => { for expr in visited_in_block(body) { if emit_enters_a_parallel_rule(grammars, world, expr) { return true; } } },
            _ => { },
        }
    }
    false
}

